<script setup>
import { onMounted, reactive, ref } from 'vue'
import { adminApi } from '@/api/admin.js'
const loading = ref(true); const saving = ref(false); const error = ref(''); const message = ref(''); const maintenance = ref(false); const saved = ref(false)
const password = reactive({ currentPassword: '', newPassword: '', confirmPassword: '' }); const passwordError = ref(''); const passwordSaved = ref(false)
const logs = ref([]); const logLoading = ref(true); const pagination = ref({ page: 1, pages: 1 })
async function load() { try { const [settings, logData] = await Promise.all([adminApi.settings(), adminApi.logs('page=1&limit=10')]); maintenance.value = settings.data.maintenanceMode; message.value = settings.data.maintenanceMessage; logs.value = logData.data; pagination.value = logData.pagination } catch (e) { error.value = e.message } finally { loading.value = false; logLoading.value = false } }
async function saveSettings() { saving.value = true; error.value = ''; try { const result = await adminApi.updateSettings({ maintenanceMode: maintenance.value, maintenanceMessage: message.value }); maintenance.value = result.data.maintenanceMode; message.value = result.data.maintenanceMessage; saved.value = true; setTimeout(() => saved.value = false, 3000) } catch (e) { error.value = e.message } finally { saving.value = false } }
async function changePassword() { passwordError.value = ''; passwordSaved.value = false; if (password.newPassword.length < 12) { passwordError.value = 'New password must be at least 12 characters.'; return } if (password.newPassword !== password.confirmPassword) { passwordError.value = 'Passwords do not match.'; return } try { await adminApi.changePassword(password); password.currentPassword = ''; password.newPassword = ''; password.confirmPassword = ''; passwordSaved.value = true } catch (e) { passwordError.value = e.message } }
onMounted(load)
</script>
<template><section><div class="mb-8"><p class="admin-eyebrow">System</p><h1 class="admin-title">Settings</h1><p class="mt-2 text-gray-500">Control the studio experience, security, and audit history.</p></div><div v-if="error" class="mb-6 rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{{ error }} <button class="ml-2 font-bold" @click="load">Retry</button></div><div v-if="loading" class="h-96 animate-pulse rounded-3xl bg-gray-200" /><div v-else class="grid max-w-6xl gap-6"><div class="rounded-3xl border border-gray-200 bg-white p-5 shadow-sm sm:p-7"><div class="flex flex-col justify-between gap-5 sm:flex-row sm:items-center"><div><p class="admin-eyebrow">Site availability</p><h2 class="admin-section-title">Maintenance mode</h2><p class="mt-2 max-w-xl text-sm leading-6 text-gray-500">Visitors are redirected to maintenance while admin routes remain available.</p></div><button class="relative h-8 w-14 rounded-full transition" :class="maintenance ? 'bg-[#17A6E3]' : 'bg-gray-300'" role="switch" :aria-checked="maintenance" @click="maintenance = !maintenance"><span class="absolute top-1 size-6 rounded-full bg-white shadow transition" :class="maintenance ? 'left-7' : 'left-1'" /></button></div><label class="admin-label mt-6">Public maintenance message<textarea v-model="message" rows="3" class="admin-input mt-2" /></label><button class="admin-button-primary mt-5" :disabled="saving" @click="saveSettings">{{ saving ? 'Saving…' : 'Save site settings' }}</button><span v-if="saved" class="ml-3 text-sm text-emerald-600">Saved to API.</span></div><div class="rounded-3xl border border-gray-200 bg-white p-5 shadow-sm sm:p-7"><p class="admin-eyebrow">Security</p><h2 class="admin-section-title">Change password</h2><p class="mt-2 text-sm text-gray-500">Changing your password revokes the current session and requires signing in again.</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><input v-model="password.currentPassword" class="admin-input" type="password" placeholder="Current password" autocomplete="current-password" /><input v-model="password.newPassword" class="admin-input" type="password" placeholder="New password (12+ characters)" autocomplete="new-password" /><input v-model="password.confirmPassword" class="admin-input sm:col-span-2" type="password" placeholder="Confirm new password" autocomplete="new-password" /></div><p v-if="passwordError" class="mt-3 text-sm text-red-600">{{ passwordError }}</p><p v-if="passwordSaved" class="mt-3 text-sm text-emerald-600">Password changed. Please sign in again.</p><button class="admin-button-secondary mt-5" @click="changePassword">Change password</button></div><div class="rounded-3xl border border-gray-200 bg-white p-5 shadow-sm sm:p-7"><div class="flex items-end justify-between"><div><p class="admin-eyebrow">Audit trail</p><h2 class="admin-section-title">Recent logs</h2></div><span class="text-xs text-gray-400">Page {{ pagination.page }} / {{ pagination.pages || 1 }}</span></div><div v-if="logLoading" class="mt-5 h-28 animate-pulse rounded-2xl bg-gray-100" /><div v-else-if="!logs.length" class="mt-5 rounded-2xl bg-gray-50 p-5 text-sm text-gray-500">No audit events yet.</div><div v-else class="mt-5 overflow-x-auto"><table class="w-full min-w-[620px] text-left text-sm"><thead class="border-b text-xs uppercase tracking-wider text-gray-400"><tr><th class="pb-3">Action</th><th class="pb-3">Resource</th><th class="pb-3">Actor</th><th class="pb-3">Date</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id" class="border-b border-gray-100 last:border-0"><td class="py-3 font-semibold">{{ log.action }}</td><td class="py-3 text-gray-500">{{ log.resourceTitle || log.resourceType || '—' }}</td><td class="py-3 text-gray-500">{{ log.actor?.email || 'System' }}</td><td class="py-3 text-gray-400">{{ new Date(log.createdAt).toLocaleString() }}</td></tr></tbody></table></div></div></div></section></template>
